// ---- generated by scripts/make_r2_tests.py of the probe: the readers
[[nodiscard]] std::string readTrapezoidFinSet(ApplicationSetterFixture& /*fixture*/,
                                              const RocketComponent& c)
{
    return listInOrder({asText(axialMethodName(as<TrapezoidFinSet>(c).getTabOffsetMethod())),
                        num(as<TrapezoidFinSet>(c).getTabOffset()),
                        num(as<TrapezoidFinSet>(c).getTabFrontEdge())});
}

[[nodiscard]] std::string readEllipticalFinSet(ApplicationSetterFixture& /*fixture*/,
                                               const RocketComponent& c)
{
    return listInOrder({asText(axialMethodName(as<EllipticalFinSet>(c).getTabOffsetMethod())),
                        num(as<EllipticalFinSet>(c).getTabOffset()),
                        num(as<EllipticalFinSet>(c).getTabFrontEdge())});
}

[[nodiscard]] std::string readFreeformFinSet(ApplicationSetterFixture& /*fixture*/,
                                             const RocketComponent& c)
{
    return listInOrder({asText(axialMethodName(as<FreeformFinSet>(c).getTabOffsetMethod())),
                        num(as<FreeformFinSet>(c).getTabOffset()),
                        num(as<FreeformFinSet>(c).getTabFrontEdge())});
}

