TEST(FinTabPositionSetter, DoesWithEveryElementWhatOpenRocketDoes)
{
    EXPECT_EQ(checkSetterScripts(kJava), Texts{});
}

// The cases x523 and x524 of the probe, through a setter of the test's own. A new fin set has no
// tab, and its tab is placed along a root of length 0 until something sets the fin's length.
TEST(FinTabPositionSetter, SetsTheMethodAndThenTheOffset)
{
    const FinTabPositionSetter setter;
    EXPECT_EQ(applyByHand(setter, ComponentKind::TRAPEZOID_FIN_SET, "relativeto=top", "0.01",
                          &readTrapezoidFinSet),
              "TOP, 0.01, 0.01");
    EXPECT_EQ(applyByHand(setter, ComponentKind::TRAPEZOID_FIN_SET, "relativeto=middle", "0.01",
                          &readTrapezoidFinSet),
              "MIDDLE, 0.01, 0.01");
}

/// What the setter does with a component of @p kind that is no fin set: the message of the
/// BugError, or "no BugError".
[[nodiscard]] std::string setTheTabOf(ComponentKind kind, std::string_view attributes)
{
    ApplicationSetterFixture   fixture;
    RocketComponent&           component = fixture.make(kind);
    WarningSet                 warnings;
    const FinTabPositionSetter setter;
    try
    {
        const Result<void> result =
            setter.set(component, "0.01", attributesOf(attributes), warnings, fixture.context());
        return result.has_value() ? "no BugError" : "failed";
    }
    catch (const BugError& error)
    {
        return error.what();
    }
}

// OpenRocket: an IllegalStateException "FinTabPositionSetter called for component Body Tube",
// before it looks at the attribute. The walk of the setter table cannot bring it about.
TEST(FinTabPositionSetter, AComponentThatIsNoFinSetIsAProgrammingError)
{
    EXPECT_NE(setTheTabOf(ComponentKind::BODY_TUBE, "relativeto=top")
                  .find("FinTabPositionSetter called for component Body Tube"),
              std::string::npos);
    EXPECT_NE(setTheTabOf(ComponentKind::BODY_TUBE, "")
                  .find("FinTabPositionSetter called for component Body Tube"),
              std::string::npos);
    // A tube fin set is no fin set.
    EXPECT_NE(setTheTabOf(ComponentKind::TUBE_FIN_SET, "relativeto=top")
                  .find("FinTabPositionSetter called for component Tube Fin Set"),
              std::string::npos);
}

